// firmware_issue row-level security and integrity — generated by `pnpm gen:migration` (02-architecture §4,
// 04-testing §3); D-31: R&D reference data, staff only, not client data.
import { randomUUID } from 'node:crypto';
import { afterAll, beforeAll, expect, inject, it } from 'vitest';
import { createTestDatabase, type TestDatabase } from '@ocs/testing';
import {
  createDatabase,
  firmwareIssue,
  inActorTransaction,
  migrateUp,
  type Database,
  type DbActor,
} from '../index.ts';

const clientA = randomUUID();
const staff: DbActor = { id: randomUUID(), kind: 'staff', clientIds: [] };
const system: DbActor = { id: randomUUID(), kind: 'system', clientIds: [], roles: ['system'] };
const userOfA: DbActor = { id: randomUUID(), kind: 'client', clientIds: [clientA] };
const partnerOfA: DbActor = { id: randomUUID(), kind: 'partner', clientIds: [clientA] };
const issueOf = (summary: string, more: Partial<typeof firmwareIssue.$inferInsert> = {}) => ({
  id: randomUUID(),
  model: 'G6',
  firmware: '3.2.1',
  summary,
  severity: 'degraded' as const,
  createdBy: staff.id,
  ...more,
});
let testDb: TestDatabase;
let database: Database;

const visibleTo = (actor: DbActor) =>
  inActorTransaction(database.db, actor, async (tx) => (await tx.select().from(firmwareIssue)).length);

beforeAll(async () => {
  testDb = await createTestDatabase(inject('postgresUrl'));
  database = createDatabase(testDb.url);
  await migrateUp(database.pool);
  await inActorTransaction(database.db, staff, (tx) =>
    tx
      .insert(firmwareIssue)
      .values([issueOf('Counts drop after 72 h uptime'), issueOf('Clock drift', { severity: 'info' })]),
  );
});

afterAll(async () => {
  await database.close();
  await testDb.drop();
});

it('staff and the system actor see the issues; clients and partners never do', async () => {
  expect(await visibleTo(staff)).toBe(2);
  expect(await visibleTo(system)).toBe(2);
  expect(await visibleTo(userOfA)).toBe(0);
  expect(await visibleTo(partnerOfA)).toBe(0);
});

it('a client cannot write', async () => {
  await expect(
    inActorTransaction(database.db, userOfA, (tx) => tx.insert(firmwareIssue).values(issueOf('X'))),
  ).rejects.toThrow();
});

it('an issue names a model, a firmware, a summary and a known severity', async () => {
  for (const bad of [{ model: ' ' }, { firmware: '' }, { summary: ' ' }, { severity: 'meh' as 'info' }]) {
    await expect(
      inActorTransaction(database.db, staff, (tx) => tx.insert(firmwareIssue).values(issueOf('Bad', bad))),
    ).rejects.toThrow();
  }
});
